-- MySQL 8 schema. IDs are UUID strings generated by the database.
CREATE TABLE organizations (
  id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  name VARCHAR(255) NOT NULL,
  settings JSON NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
);

INSERT INTO organizations(id, name)
VALUES ('00000000-0000-0000-0000-000000000001', 'KnowGrow Default Organisation');

CREATE TABLE departments (
  id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  org_id CHAR(36) NOT NULL,
  name VARCHAR(255) NOT NULL,
  FOREIGN KEY (org_id) REFERENCES organizations(id)
);

CREATE TABLE teams (
  id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  org_id CHAR(36) NOT NULL,
  department_id CHAR(36) NULL,
  name VARCHAR(255) NOT NULL,
  parent_team_id CHAR(36) NULL,
  FOREIGN KEY (org_id) REFERENCES organizations(id),
  FOREIGN KEY (department_id) REFERENCES departments(id),
  FOREIGN KEY (parent_team_id) REFERENCES teams(id)
);

CREATE TABLE users (
  id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  org_id CHAR(36) NOT NULL,
  team_id CHAR(36) NULL,
  department_id CHAR(36) NULL,
  name VARCHAR(255) NOT NULL,
  email VARCHAR(255) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NULL,
  role VARCHAR(30) NOT NULL DEFAULT 'Employee',
  job_title VARCHAR(255) NULL,
  department VARCHAR(255) NOT NULL DEFAULT 'General',
  team VARCHAR(255) NOT NULL DEFAULT 'Unassigned',
  avatar VARCHAR(10) NOT NULL DEFAULT '',
  status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
  left_at DATETIME(6) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT users_role_check CHECK (role IN ('Employee','Manager','Mentor','HR Specialist','Department Head')),
  FOREIGN KEY (org_id) REFERENCES organizations(id),
  FOREIGN KEY (team_id) REFERENCES teams(id),
  FOREIGN KEY (department_id) REFERENCES departments(id)
);

CREATE TABLE topics (
  id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  org_id CHAR(36) NOT NULL,
  name VARCHAR(255) NOT NULL,
  parent_id CHAR(36) NULL,
  criticality INT NOT NULL DEFAULT 3,
  CONSTRAINT topics_crit_check CHECK (criticality BETWEEN 1 AND 5),
  UNIQUE (org_id, name),
  FOREIGN KEY (org_id) REFERENCES organizations(id),
  FOREIGN KEY (parent_id) REFERENCES topics(id)
);

CREATE TABLE sources (
  id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  org_id CHAR(36) NOT NULL,
  type VARCHAR(50) NOT NULL,
  config JSON NULL,
  last_synced_at DATETIME(6) NULL,
  FOREIGN KEY (org_id) REFERENCES organizations(id)
);

CREATE TABLE documents (
  id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  org_id CHAR(36) NOT NULL,
  source_id CHAR(36) NULL,
  external_id VARCHAR(255) NULL,
  title VARCHAR(500) NOT NULL,
  author_id CHAR(36) NULL,
  content_hash VARCHAR(128) NULL,
  url VARCHAR(1000) NULL,
  last_modified DATETIME(6) NULL,
  FOREIGN KEY (org_id) REFERENCES organizations(id),
  FOREIGN KEY (source_id) REFERENCES sources(id),
  FOREIGN KEY (author_id) REFERENCES users(id)
);

CREATE TABLE document_topics (
  document_id CHAR(36) NOT NULL,
  topic_id CHAR(36) NOT NULL,
  confidence FLOAT NOT NULL DEFAULT 1.0,
  PRIMARY KEY (document_id, topic_id),
  FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE CASCADE,
  FOREIGN KEY (topic_id) REFERENCES topics(id) ON DELETE CASCADE
);

CREATE TABLE user_topics (
  user_id CHAR(36) NOT NULL,
  topic_id CHAR(36) NOT NULL,
  expertise_score FLOAT NOT NULL DEFAULT 0,
  evidence_count INT NOT NULL DEFAULT 0,
  PRIMARY KEY (user_id, topic_id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (topic_id) REFERENCES topics(id) ON DELETE CASCADE
);

CREATE TABLE gaps (
  id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  org_id CHAR(36) NOT NULL,
  topic_id CHAR(36) NOT NULL,
  type VARCHAR(20) NOT NULL,
  severity VARCHAR(20) NOT NULL,
  score FLOAT NOT NULL,
  explanation TEXT NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'OPEN',
  detected_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  resolved_at DATETIME(6) NULL,
  CONSTRAINT gaps_type_check CHECK (type IN ('COVERAGE','CONCENTRATION','STALENESS','DEMAND','ATTRITION','SKILL')),
  CONSTRAINT gaps_sev_check CHECK (severity IN ('LOW','MEDIUM','HIGH','CRITICAL')),
  FOREIGN KEY (org_id) REFERENCES organizations(id),
  FOREIGN KEY (topic_id) REFERENCES topics(id)
);

CREATE TABLE recommendations (
  id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  gap_id CHAR(36) NOT NULL,
  action_type VARCHAR(50) NOT NULL,
  assignee_id CHAR(36) NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'OPEN',
  due_date DATE NULL,
  FOREIGN KEY (gap_id) REFERENCES gaps(id) ON DELETE CASCADE,
  FOREIGN KEY (assignee_id) REFERENCES users(id)
);

CREATE TABLE audit_log (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  user_id CHAR(36) NULL,
  action VARCHAR(100) NOT NULL,
  entity VARCHAR(255) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
);

CREATE TABLE user_skills (
  user_id CHAR(36) NOT NULL,
  id VARCHAR(100) NOT NULL,
  name VARCHAR(255) NOT NULL,
  category VARCHAR(255) NOT NULL DEFAULT '',
  current_level VARCHAR(20) NULL,
  required_level VARCHAR(20) NOT NULL,
  status VARCHAR(100) NOT NULL DEFAULT '',
  PRIMARY KEY (user_id, id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE learning_items (
  user_id CHAR(36) NOT NULL,
  id VARCHAR(100) NOT NULL,
  title VARCHAR(500) NOT NULL,
  skill VARCHAR(255) NOT NULL DEFAULT '',
  status VARCHAR(50) NOT NULL,
  progress INT NOT NULL DEFAULT 0,
  due VARCHAR(50) NOT NULL DEFAULT '',
  type VARCHAR(100) NOT NULL DEFAULT '',
  PRIMARY KEY (user_id, id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE notifications (
  user_id CHAR(36) NOT NULL,
  id VARCHAR(100) NOT NULL,
  title VARCHAR(500) NOT NULL,
  detail TEXT NOT NULL,
  date VARCHAR(50) NOT NULL DEFAULT '',
  is_read BOOLEAN NOT NULL DEFAULT FALSE,
  kind VARCHAR(100) NOT NULL DEFAULT '',
  PRIMARY KEY (user_id, id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX idx_users_org ON users(org_id);
CREATE INDEX idx_gaps_org_status ON gaps(org_id, status);
CREATE INDEX idx_user_topics_topic ON user_topics(topic_id);
